<script setup lang="ts">
import ZipEditBar from '@/components/archive/ZipEditBar.vue'
import {useAppStore} from '@/stores/app'
import {nextTick} from 'vue'
import {onMounted,onUnmounted,ref,watch} from 'vue'
import {open} from '@tauri-apps/api/dialog'
import {useRouter} from 'vue-router'
import {useSourceComparisonStore} from '@/stores/sourceComparison'
import {comparisonLabels,hasPair,type ComparisonSide} from '@/types/sourceComparison'
import {libraryBytes} from '@/types/archiveLibrary'
import ComparisonRetrievalDialog from '@/components/archive/ComparisonRetrievalDialog.vue'
import {archiveInspectionMessageForDisplay} from '@/utils/taskFailure'
const displayError=(message:string)=>archiveInspectionMessageForDisplay(message.replace(/\[comparison:[^\]]+\]\s*/g,''))
import Modal from '@/components/ui/Modal.vue'
import ComparisonPasswordField from '@/components/archive/ComparisonPasswordField.vue'
const credentialsSide=ref<ComparisonSide>()
const comparison=useSourceComparisonStore(),router=useRouter(),dialog=ref(false)
const sides:ComparisonSide[]=['left','right']
onMounted(()=>void comparison.attach());onUnmounted(()=>comparison.detach())
watch(()=>[comparison.query,comparison.filter],()=>comparison.page=1)
watch(()=>comparison.pages,value=>comparison.page=Math.min(comparison.page,value))
async function choose(side:ComparisonSide,directory:boolean){try{const queued=import.meta.env.VITE_DESKTOP_E2E==='1'?window.__LONG_DECOMPRESS_DESKTOP_E2E__?.takeDesktopDialogSelection():undefined;const path=queued===undefined?await open({directory,multiple:false,title:`选择${side==='left'?'左侧':'右侧'}${directory?'文件夹':'ZIP'}`,filters:undefined}):queued;if(typeof path==='string')await comparison.read(side,path)}catch(error){comparison.sides[side].error=String(error)}}
function goQueue(){dialog.value=false;void router.push('/decompress')}
const packageEditor=ref<InstanceType<typeof ZipEditBar>>()
async function preparedPackage(source:string){comparison.packageSource=source;dialog.value=false;await nextTick();packageEditor.value?.openReview()}
function browsePackage(path:string,options?:Parameters<ReturnType<typeof useAppStore>['openArchiveInBrowser']>[1]){useAppStore().openArchiveInBrowser(path,options);void router.push('/browser')}
</script>
<template>
 <div class="comparison-page custom-scrollbar" data-testid="source-comparison-page">
  <header class="page-heading"><div><span class="eyebrow">COMPARE YOUR FILES</span><h1>资料对比</h1><p class="muted">两份资料放在一起看，找到差异，再取回需要的内容。</p></div><button class="button" @click="goQueue"><i class="pi pi-list"/>查看取回任务</button></header>
  <div class="source-grid" data-testid="comparison-sources"><section v-for="side in sides" :key="side" class="source-card" :data-comparison-source="side"><div class="source-title"><h2><span>{{ side==='left'?'L':'R' }}</span>{{ side==='left'?'左侧来源':'右侧来源' }}</h2><span class="tag">{{ comparison.sides[side].source?.source.kind==='zip'?'ZIP':comparison.sides[side].source?'文件夹':'尚未选择' }}</span></div><div class="path-field"><input v-model="comparison.sides[side].path" @input="comparison.editPath(side)" :data-comparison-path="side" :disabled="comparison.busy||!!comparison.verifyJob||!!comparison.sides[side].jobId" placeholder="选择或输入文件夹 / ZIP / ZIP 分卷路径"><button class="button" :data-comparison-read="side" :disabled="comparison.busy||!!comparison.verifyJob||!!comparison.sides[side].jobId||!comparison.sides[side].path.trim()" @click="comparison.read(side,comparison.sides[side].path)">读取</button></div><div class="source-actions"><button class="button" :data-comparison-folder="side" :disabled="comparison.busy||!!comparison.verifyJob||!!comparison.sides[side].jobId" @click="choose(side,true)"><i class="pi pi-folder"/>文件夹</button><button class="button" :data-comparison-zip="side" :disabled="comparison.busy||!!comparison.verifyJob||!!comparison.sides[side].jobId" @click="choose(side,false)"><i class="pi pi-box"/>ZIP</button><button v-if="comparison.sides[side].jobId" class="link" :data-comparison-stop="side" @click="comparison.cancel(side)">停止读取</button><span class="muted">{{ comparison.sides[side].jobId?'正在读取 · '+comparison.sides[side].readCount+' 项':comparison.sides[side].source?comparison.sides[side].source!.entries.length+' 项 · 完整清单已读取':'选择固定资料进行本次对比' }}</span></div><div v-if="comparison.sides[side].source?.source.kind==='zip'" class="source-actions"><button class="button" :data-comparison-password="side" :disabled="comparison.busy||!!comparison.verifyJob" @click="credentialsSide=side"><i class="pi pi-key"/>来源密码</button><span class="muted">{{ comparison.sides[side].source?.source.encrypted?'包含密码内容 · '+(comparison.sides[side].password?'本次已填写':'核对或取回前填写'):'没有密码内容' }}</span></div><p v-if="comparison.sides[side].error" class="error" :data-comparison-error="side" role="status">{{ displayError(comparison.sides[side].error) }}</p></section></div>
  <ZipEditBar v-if="comparison.packageSource" ref="packageEditor" :source-path="comparison.packageSource" directory="" @open-result="browsePackage"/>
  <p class="scope-note"><i class="pi pi-info-circle"/>先看类型、大小和时间，再按需核对实际内容。支持文件夹与 Store/Deflate ZIP，含 AES/ZipCrypto 密码、完整数字与标准分卷；其他方法及缺卷救援继续使用原文件浏览器。</p>
  <template v-if="comparison.ready">
   <div class="stats"><button @click="comparison.filter='left_only'"><strong>{{ comparison.counts.left_only||0 }}</strong><span>仅左侧</span></button><button @click="comparison.filter='right_only'"><strong>{{ comparison.counts.right_only||0 }}</strong><span>仅右侧</span></button><button data-testid="comparison-changed-stat" @click="comparison.filter='changes'"><strong>{{ comparison.changedCount }}</strong><span>两侧条目变化</span></button><button data-testid="comparison-unverified-stat" @click="comparison.filter='unverified'"><strong>{{ comparison.unverifiedCount }}</strong><span>待核对 / 未完成</span></button></div>
   <section class="content-check" data-testid="comparison-content-panel">
    <div class="check-heading"><div><h2><i class="pi pi-check-circle"/>核对实际内容</h2><p class="muted">只读取双方都有的文件；同大小逐侧读取完整内容，确认后保留结论。每次最多 2000 项。</p></div><div class="actions"><button v-if="!comparison.verifyJob" class="button" :disabled="comparison.busy||!comparison.selectedCount" data-testid="comparison-verify-selected" @click="comparison.verifySelected">核对所选未完成项</button><button v-if="!comparison.verifyJob" class="button primary" :disabled="comparison.busy" data-testid="comparison-verify-filtered" @click="comparison.verifyFiltered">核对当前筛选</button><button v-else class="button" :disabled="comparison.stopping" data-testid="comparison-verify-stop" @click="comparison.stopVerification">{{ comparison.stopping?'正在停止…':'停止核对' }}</button></div></div>
    <div class="verified-counts"><button @click="comparison.filter='same'">内容相同 <strong>{{ comparison.counts.same||0 }}</strong></button><button @click="comparison.filter='different'">内容不同 <strong>{{ comparison.counts.different||0 }}</strong></button><button @click="comparison.filter='metadata'">仅时间变化 <strong>{{ comparison.counts.metadata||0 }}</strong></button><button @click="comparison.filter='unverified'">查看待核对 / 未完成项</button></div>
    <div v-if="comparison.verifyNote" class="check-progress" role="status" data-testid="comparison-content-progress"><p>{{ comparison.verifyNote }}</p><template v-if="comparison.verifyProgress.total"><p>{{ comparison.verifyProgress.completed }} / {{ comparison.verifyProgress.total }} 项 · 已读取 {{ libraryBytes(comparison.verifyProgress.processedBytes) }} / {{ libraryBytes(comparison.verifyProgress.totalBytes) }}</p><progress :value="comparison.verifyProgress.totalBytes?comparison.verifyProgress.processedBytes:comparison.verifyProgress.completed" :max="comparison.verifyProgress.totalBytes||comparison.verifyProgress.total||1"/><p v-if="comparison.verifyJob&&comparison.verifyProgress.path" class="muted">{{ comparison.verifyProgress.side==='left'?'左侧':comparison.verifyProgress.side==='right'?'右侧':'' }} {{ comparison.verifyProgress.path }}</p></template></div>
   </section>
   <div class="toolbar"><input v-model="comparison.query" data-testid="comparison-search" placeholder="搜索相对路径或文件名"><select v-model="comparison.filter" data-testid="comparison-filter"><option value="all">全部条目</option><option value="changes">两侧条目变化</option><option value="unverified">待核对 / 未完成</option><option v-for="(label,kind) in comparisonLabels" :key="kind" :value="kind">{{ label }}</option></select><span class="muted">{{ comparison.filtered.length }} 项 · 每页 50 项</span></div>
   <div class="selection-bar" data-testid="comparison-selection-bar"><div><strong>已选 {{ comparison.selectedCount }} 项</strong><small>左 {{ comparison.selected.left.size }} · 右 {{ comparison.selected.right.size }}</small></div><div class="actions"><button class="button" :disabled="comparison.busy||!!comparison.verifyJob" data-testid="comparison-select-left-page" @click="comparison.togglePage('left')">勾选 / 取消本页左侧</button><button class="button" :disabled="comparison.busy||!!comparison.verifyJob" data-testid="comparison-select-right-page" @click="comparison.togglePage('right')">勾选 / 取消本页右侧</button><button class="link" :disabled="comparison.busy||!!comparison.verifyJob||!comparison.selectedCount" @click="comparison.clear">清空</button><button class="button primary" :disabled="comparison.busy||!!comparison.verifyJob||!comparison.selectedCount" data-testid="comparison-retrieve-open" @click="comparison.error='';dialog=true"><i class="pi pi-download"/>处理所选</button></div></div>
   <p v-if="comparison.error" class="error" role="alert">{{ displayError(comparison.error) }}</p><p v-if="comparison.notice" class="scope-note" data-testid="comparison-notice">{{ comparison.notice }} <button class="link" @click="goQueue">前往解压中心</button></p>
   <div class="row-list" data-testid="comparison-results"><article v-for="row in comparison.visible" :key="row.path" class="comparison-row" :data-comparison-row="row.path"><button class="row-heading" :aria-expanded="comparison.expanded===row.path" :data-comparison-expand="row.path" @click="comparison.expanded=comparison.expanded===row.path?'':row.path"><strong>{{ row.path }}</strong><span class="tag" :class="{changed:!['candidate','directory','same'].includes(row.kind),confirmed:row.kind==='same',incomplete:row.kind==='unreadable'}">{{ comparisonLabels[row.kind] }}</span><i :class="comparison.expanded===row.path?'pi pi-chevron-up':'pi pi-chevron-down'"/></button><div class="pair"><div v-for="side in sides" :key="side" class="entry" :class="{missing:!row[side]}"><label v-if="row[side]" class="entry-choice"><input type="checkbox" :checked="comparison.selected[side].has(row.path)" :disabled="comparison.busy||!!comparison.verifyJob||!row[side]!.selectable" :data-comparison-select="side+':'+row.path" :aria-label="'选择'+(side==='left'?'左侧 ':'右侧 ')+row.path" @change="comparison.toggle(side,row.path)"><i :class="row[side]!.directory?'pi pi-folder':'pi pi-file'"/><span><strong>{{ side==='left'?'左侧':'右侧' }} · {{ row[side]!.directory?'文件夹':libraryBytes(row[side]!.size) }}</strong><small>{{ row[side]!.directory?(row[side]!.selectable?'空目录，可取回':'请选择下层文件'):row[side]!.modified||'未记录时间' }}</small></span></label><p v-else>{{ side==='left'?'左侧':'右侧' }}没有这一项</p></div></div><div v-if="comparison.expanded===row.path" class="row-details" :data-comparison-details="row.path"><p>{{ row.reason }}</p><button v-if="hasPair(row)" class="button mt-2" :data-comparison-verify="row.path" :disabled="comparison.busy||!!comparison.verifyJob" @click="comparison.verify([row.path],true)">{{ comparison.verdicts[row.path]?'重新核对这一项':'核对这一项' }}</button><p v-for="side in sides" v-show="row[side]" :key="side" class="muted">{{ side==='left'?'左侧':'右侧' }}：{{ comparison.sides[side].source?.source.path }}{{ comparison.sides[side].source?.source.kind==='zip'?'!/':'/' }}{{ row.path }}</p></div></article><div v-if="!comparison.visible.length" class="empty"><i class="pi pi-search"/><h3>{{ comparison.rows.length?'没有符合筛选的条目':'两侧均为空' }}</h3><p class="muted">{{ comparison.rows.length?'试试其他文件名或筛选条件。':'未发现文件或子目录；不会把空清单当作内容相同证明。' }}</p></div></div>
   <footer class="pagination"><button class="button" :disabled="comparison.page<=1" data-testid="comparison-previous" @click="comparison.page--">上一页</button><span>{{ comparison.page }} / {{ comparison.pages }}</span><button class="button" :disabled="comparison.page>=comparison.pages" data-testid="comparison-next" @click="comparison.page++">下一页</button></footer>
  </template>
  <section v-else class="empty"><i class="pi pi-arrows-h"/><h3>先选择左右两份资料</h3><p class="muted">文件夹与 ZIP 可以自由组合。读取完成后，按相对路径对齐查看，并分别勾选需要保留的内容。</p></section>
  <Modal v-if="credentialsSide" :visible="true" :title="(credentialsSide==='left'?'左侧':'右侧')+'来源密码'" icon="pi pi-key" size="md" @update:visible="credentialsSide=undefined"><p class="muted mb-4">{{ comparison.sides[credentialsSide].source?.name }} · 不改变来源和已完成的内容结论。</p><ComparisonPasswordField v-model:password="comparison.sides[credentialsSide].password" v-model:encoding="comparison.sides[credentialsSide].encoding" :test-id="'comparison-password-'+credentialsSide"/><template #footer><button class="button primary" data-testid="comparison-password-done" @click="credentialsSide=undefined">完成，继续处理</button></template></Modal>
  <ComparisonRetrievalDialog v-if="dialog" @close="dialog=false" @queue="goQueue" @prepared="preparedPackage"/>
 </div>
</template>
<style scoped>
