der-radius:10px;padding:9px 12px;background:var(--bg-input);color:var(--text-content);min-width:0}.button.primary{background:var(--dynamic-accent);color:white}.button:disabled,.link:disabled{opacity:.45}.link{font-size:11px;color:var(--dynamic-accent)}.source-grid,.pair{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px}.source-card{padding:18px;border:1px solid var(--border-subtle);border-radius:16px;background:var(--bg-card);min-width:0}.source-title{display:flex;align-items:center;justify-content:space-between;gap:10px}.tag{font-size:10px;padding:4px 8px;border:1px solid var(--border-subtle);border-radius:20px;color:var(--text-muted);white-space:nowrap;flex-shrink:0}.tag.changed{color:#d97706;border-color:color-mix(in srgb,#d97706 30%,transparent);background:color-mix(in srgb,#d97706 5%,transparent)}.path-field{display:flex;gap:8px;min-width:0;margin-top:16px}.path-field input,.toolbar input,.toolbar select{min-width:0;border:1px solid var(--border-subtle);border-radius:10px;background:var(--bg-input);font-size:11px;padding:10px 12px;color:var(--text-content)}.path-field input{flex:1;width:0}.path-field button{flex-shrink:0}.source-actions,.actions{display:flex;align-items:center;gap:8px;flex-wrap:wrap}.source-actions{margin-top:12px}.error{font-size:11px;color:#d97706;line-height:1.9;overflow-wrap:anywhere;margin-top:12px}.scope-note{font-size:11px;line-height:1.9;color:var(--text-muted);padding:12px 16px;background:var(--bg-card);border:1px solid var(--border-subtle);border-radius:12px;margin:18px 0;overflow-wrap:anywhere}.scope-note i{color:var(--dynamic-accent);margin-right:6px}.stats{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px;margin-bottom:18px}.stats button{text-align:left;padding:16px 18px;background:var(--bg-card);border:1px solid var(--border-subtle);border-radius:14px}.stats strong{display:block;font-size:22px;font-weight:900;color:var(--dynamic-accent)}.stats span{display:block;font-size:10px;line-height:1.8;co